test:
assert parse_type(' [ int , (str, ()) ] ') == ('int', ('str', ()))
assert parse_type('(x,)') == ('x',)
assert format_type(('int', ('str', ()))) == '(int,(str,()))'
for text in ['', '(int', 'int)', '(,)', '(int,,str)', '() tail']:
    try:
        parse_type(text)
        assert False, text
    except ValueError:
        pass

assert infer_return_type(['int', 'int'], ['T', 'T'], 'T') == 'int'
assert infer_return_type([('int', 'str')], ['T'], 'T') == ('int', 'str')
for args in [(['int', 'str'], ['T', 'T'], 'T'), ([('int',)], [('T', 'U')], 'T'), (['int'], ['T'], 'U'), (['int'], ['T', 'U'], 'T')]:
    try:
        infer_return_type(*args)
        assert False, args
    except ValueError:
        pass
